from collections import Counter

class Solution:
    def deleteAndEarn(self, nums: list[int]) -> int:
        count = Counter(nums)
        max_val = max(nums)
        dp = [0] * (max_val + 1)
        dp[1] = count.get(1, 0) * 1
        for i in range(2, max_val + 1):
            dp[i] = max(dp[i - 1], dp[i - 2] + i * count.get(i, 0))
        return dp[max_val]

